interface Env { SUPABASE_URL:string; SUPABASE_ANON_KEY:string; SUPABASE_SERVICE_ROLE_KEY:string; BROWSER:{quickAction(action:'pdf',input:Record<string,unknown>):Promise<Response>}; }
type Json=Record<string,unknown>;
async function ownerFromRequest(request:Request,env:Env):Promise<string|null>{
 const token=request.headers.get("Authorization")?.match(/^Bearer\s+(\S+)$/i)?.[1];if(!token)return null;
 const response=await fetch(env.SUPABASE_URL+"/auth/v1/user",{headers:{apikey:env.SUPABASE_ANON_KEY,Authorization:"Bearer "+token},signal:AbortSignal.timeout(10000)});
 if(!response.ok)return null;const user=await response.json() as {id?:string};return user.id??null;
}
async function db<T>(env:Env,path:string,init:RequestInit={}):Promise<T>{
 const response=await fetch(env.SUPABASE_URL+"/rest/v1/"+path,{...init,signal:init.signal??AbortSignal.timeout(12000),headers:{apikey:env.SUPABASE_SERVICE_ROLE_KEY,Authorization:"Bearer "+env.SUPABASE_SERVICE_ROLE_KEY,"Content-Type":"application/json",...init.headers}});
 const raw=await response.text();if(!response.ok)throw new Error("DATABASE_"+response.status+": "+raw.slice(0,300));return raw?JSON.parse(raw) as T:undefined as T;
}
function obj(value:unknown):Json{return value&&typeof value==="object"&&!Array.isArray(value)?value as Json:{};}
function defaultDocumentPolicy(type:string):Json{
 const purchaseTypes=["purchase_order","purchase_confirmation","request_for_quotation"].includes(type);
 const shipmentTypes=["commercial_invoice","packing_list","shipping_instructions","shipper_letter_instruction","vgm_declaration","packing_declaration"].includes(type);
 const shipmentOnly=["vgm_declaration","packing_declaration"].includes(type);
 const quoteTypes=["quotation","request_for_quotation"].includes(type);
 const requiredFields=type==="vgm_declaration"?["seller_name","buyer_name","shipment.total_gross_weight"]:type==="packing_declaration"?["seller_name","buyer_name","shipment.total_packages","shipment.total_gross_weight"]:type==="packing_list"?["seller_name","seller_address","buyer_name","buyer_shipping_address","items","shipment.total_packages","shipment.total_gross_weight","shipment.total_net_weight"]:["shipping_instructions","shipper_letter_instruction"].includes(type)?["seller_name","buyer_name","buyer_shipping_address"]:type==="bill_of_exchange"?["seller_name","buyer_name","currency_code","totals.grand_total"]:["tax_invoice","credit_note","debit_note","commercial_invoice"].includes(type)?["seller_name","seller_address","buyer_name","buyer_address","currency_code","items","totals.grand_total"]:["proforma_invoice","sales_contract","sales_confirmation","purchase_order","purchase_confirmation","quotation","request_for_quotation"].includes(type)?["seller_name","seller_address","buyer_name","buyer_address","currency_code","items","totals.grand_total"]:["origin_declaration","origin_certificate_application","non_asbestos_declaration"].includes(type)?["seller_name","seller_address","buyer_name","buyer_address","items"]:[];
 return {enabled:true,allowedSources:purchaseTypes?["blank","purchase_order"]:shipmentOnly?["sales_order","shipment"]:shipmentTypes?["blank","sales_order","shipment"]:["blank","sales_order"],allowBlankCreation:!shipmentOnly,requireOrderOnConfirmation:false,requireLockedOrderWhenOrderLinked:!purchaseTypes&&!quoteTypes,requireShipmentWhenOrderLinked:shipmentTypes,allowStandaloneConfirmation:!shipmentOnly,requireReview:false,requiredFields,requiredOnDraftFields:[],editableFields:["seller_name","seller_address","buyer_name","buyer_address","buyer_shipping_address","contact_name","contact_email","contact_phone","notes","customer_reference","items"]};
}
function str(value:unknown,max=240):string{return typeof value==="string"?value.trim().slice(0,max):"";}
function hasAddress(value:unknown):boolean{if(typeof value==="string")return value.trim().length>0;return Object.values(obj(value)).some(item=>typeof item==="string"&&item.trim().length>0);}
function decimalScaled(value:unknown):bigint|null{const text=typeof value==="string"?value:typeof value==="number"?String(value):"";if(!/^(?:0|[1-9]\d*)(?:\.\d{1,6})?$/.test(text))return null;const [whole,fraction=""]=text.split(".");try{return BigInt(whole)*1000000n+BigInt((fraction+"000000").slice(0,6));}catch{return null;}}
function validLine(quantity:unknown,price:unknown,discount:unknown,taxRate:unknown):boolean{const q=decimalScaled(quantity),p=decimalScaled(price),d=decimalScaled(discount),t=decimalScaled(taxRate);return q!==null&&p!==null&&d!==null&&t!==null&&q>0n&&p>=0n&&d>=0n&&t>=0n&&d*1000000n<=q*p;}
function calculateShipmentInvoiceTotals(shipment:Json,orderItems:Json[],snapshot:Json):Json{
 const shipmentItems=Array.isArray(shipment.trade_shipment_items)?shipment.trade_shipment_items as Json[]:[];
 const lines=shipmentItems.map(item=>{const line=orderItems.find(row=>row.id===item.order_line_id)??{};const quantity=Math.max(0,Number(item.ship_qty)||0);const ordered=Math.max(0,Number(line.quantity)||0);const unitPrice=Math.max(0,Number(line.unit_price)||0);const lineDiscount=ordered>0?Math.max(0,Number(line.discount_amount)||0)*quantity/ordered:0;const net=Math.max(0,quantity*unitPrice-lineDiscount);return {net,quantity,lineDiscount,taxRate:Math.max(0,Number(line.tax_rate)||0)};});
 const productSubtotal=lines.reduce((sum,line)=>sum+line.net,0);
 const lineDiscountTotal=lines.reduce((sum,line)=>sum+line.lineDiscount,0);
 const orderTotals=obj(snapshot.totals);const orderedProductSubtotal=Math.max(0,Number(orderTotals.product_subtotal)||0);const orderDiscount=Math.max(0,Number(orderTotals.order_discount)||0);
 const allocatedOrderDiscount=orderedProductSubtotal>0?Math.min(productSubtotal,orderDiscount*productSubtotal/orderedProductSubtotal):0;
 const taxMode=str(snapshot.tax_mode,20)||"exclusive";const taxFactor=productSubtotal>0?Math.max(0,(productSubtotal-allocatedOrderDiscount)/productSubtotal):1;
 const taxTotal=lines.reduce((sum,line)=>{const base=line.net*taxFactor;return sum+(taxMode==="inclusive"?(line.taxRate>0?base*line.taxRate/(100+line.taxRate):0):base*line.taxRate/100);},0);
 const grandTotal=productSubtotal-allocatedOrderDiscount+(taxMode==="inclusive"?0:taxTotal);
 return {product_subtotal:Number(productSubtotal.toFixed(2)),line_discount_total:Number(lineDiscountTotal.toFixed(2)),order_discount:Number(allocatedOrderDiscount.toFixed(2)),charge_subtotal:0,tax_total:Number(taxTotal.toFixed(2)),grand_total:Number(grandTotal.toFixed(2)),tax_mode:taxMode,calculation_scope:"this_shipment_products_only",requires_review:true};
}

function htmlEscape(value:unknown):string{return String(value??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;");}
